"use client"

import { cn } from "@/lib/utils"
import { EntityImage } from "@/registry/mrdoge-ui/entity-image/entity-image"
import {
  LiveIndicator,
  type LiveIndicatorStatus,
} from "@/registry/mrdoge-ui/live-indicator/live-indicator"
import {
  OddsSelector,
  type OddsOption,
} from "@/registry/mrdoge-ui/odds-selector/odds-selector"

export interface MatchCardTeam {
  name: string
  logoUrl?: string
  /** Shown as a small red-card marker (position set by MatchCardProps.redCardPosition) once the match is live or finished. */
  redCards?: number
}

export interface MatchCardOdds {
  /** Market name, e.g. "Match Result". Not currently rendered. */
  market: string
  options: OddsOption[]
}

export interface MatchCardDataProps {
  loading?: false
  status: LiveIndicatorStatus
  kickoff?: Date | string
  elapsed?: string
  /**
   * Clock format for the kickoff time.
   *
   * @defaultValue "24h"
   */
  timeFormat?: "12h" | "24h"
  home: MatchCardTeam
  away: MatchCardTeam
  homeScore?: number
  awayScore?: number
  /**
   * Where the red-card marker renders relative to each team row: "left"
   * (next to the team name) or "right" (next to the score).
   *
   * @defaultValue "right"
   */
  redCardPosition?: "left" | "right"
  /**
   * Renders a labeled odds card when provided. Any market works — Match
   * Card doesn't care which one, it just needs a name and options.
   */
  odds?: MatchCardOdds
  /** Shows a skeleton in the odds area while set. Ignored once `odds` is provided. */
  oddsLoading?: boolean
  /**
   * Where the odds card renders. Falls back to "bottom" below a `@lg`
   * (32rem) container width.
   *
   * @defaultValue "bottom"
   */
  oddsPosition?: "bottom" | "right"
  selectedOddsId?: string
  /** Called with the pressed option's id, or `undefined` when pressing the already-selected option deselects it. */
  onSelectOdds?: (id: string | undefined) => void
  className?: string
}

interface MatchCardLoadingProps {
  /** Renders a skeleton with the same dimensions instead — no other prop is needed. */
  loading: true
  /** Reserves space for an odds row/column in the skeleton too. */
  oddsLoading?: boolean
  /** Same as MatchCardDataProps.oddsPosition. */
  oddsPosition?: "bottom" | "right"
  className?: string
}

export type MatchCardProps = MatchCardDataProps | MatchCardLoadingProps

function RedCardIndicator({ count }: { count: number }) {
  return (
    <div className="flex items-center gap-0.5">
      {count > 1 ? (
        <span className="text-[11px] font-bold tabular-nums text-destructive">x{count}</span>
      ) : null}
      <span className="block h-3 w-2 shrink-0 rounded-[1.5px] bg-destructive" />
    </div>
  )
}

function TeamRow({
  team,
  score,
  showScore,
  showRedCards,
  redCardPosition,
  live,
  dimmed,
}: {
  team: MatchCardTeam
  score?: number
  showScore: boolean
  showRedCards: boolean
  redCardPosition: "left" | "right"
  /** True while the match is in progress (live/paused/intermission/interrupted) — the score reads in the live color. */
  live: boolean
  /** True for the losing side once the match is finished. */
  dimmed: boolean
}) {
  const redCard =
    showRedCards && team.redCards ? <RedCardIndicator count={team.redCards} /> : null

  return (
    <div className="flex items-center justify-between gap-2">
      <div className="flex min-w-0 items-center gap-2">
        <EntityImage src={team.logoUrl} name={team.name} size="sm" />
        <span className="truncate text-sm font-medium">{team.name}</span>
        {redCardPosition === "left" ? redCard : null}
      </div>
      <div className="flex shrink-0 items-center gap-2.5">
        {redCardPosition === "right" ? redCard : null}
        {showScore ? (
          <span
            className={cn(
              "text-sm font-semibold tabular-nums",
              live && "text-destructive",
              dimmed && "text-muted-foreground"
            )}
          >
            {score ?? 0}
          </span>
        ) : null}
      </div>
    </div>
  )
}

function TeamRowSkeleton({ nameWidth }: { nameWidth: string }) {
  return (
    <div className="flex items-center justify-between gap-2">
      <div className="flex min-w-0 items-center gap-2">
        <span className="size-5 shrink-0 animate-pulse rounded-full bg-muted" />
        <span className={cn("h-3 animate-pulse rounded bg-muted", nameWidth)} />
      </div>
      <span className="h-3 w-4 shrink-0 animate-pulse rounded bg-muted" />
    </div>
  )
}

/** Same shape as OddsSelector's button grid, sized to match its real height. */
function OddsSkeleton() {
  return (
    <div className="flex h-full flex-col">
      <div className="grid flex-1 auto-cols-fr grid-flow-col divide-x">
        {[0, 1, 2].map((i) => (
          <div key={i} className="flex flex-col items-center justify-center gap-0.5 px-2 py-2.5">
            <div className="flex h-4 items-center">
              <span className="h-2.5 w-4 animate-pulse rounded bg-muted" />
            </div>
            <div className="flex h-5 items-center">
              <span className="h-3 w-10 animate-pulse rounded bg-muted" />
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

/**
 * Matches MatchCard's real dimensions exactly, so nothing shifts when
 * live data arrives. Exported separately too, for a loading list of
 * several cards before any of them have data yet.
 */
export function MatchCardSkeleton({
  className,
  oddsLoading,
  oddsPosition = "bottom",
}: {
  className?: string
  oddsLoading?: boolean
  oddsPosition?: "bottom" | "right"
}) {
  const wantsRow = oddsLoading && oddsPosition === "right"

  return (
    <div
      className={cn(
        "@container w-full overflow-hidden rounded-xl border bg-card text-card-foreground",
        className
      )}
    >
      <div className={cn(wantsRow && "@lg:flex @lg:items-stretch")}>
        <div className={cn("flex flex-1 gap-3 px-3 py-3", wantsRow && "@lg:min-w-0")}>
          <div className="flex w-11 shrink-0 items-center justify-center border-r pr-3">
            <span className="h-3 w-7 animate-pulse rounded bg-muted" />
          </div>
          <div className="flex min-w-0 flex-1 flex-col justify-center gap-2">
            <TeamRowSkeleton nameWidth="w-24" />
            <TeamRowSkeleton nameWidth="w-20" />
          </div>
        </div>
        {oddsLoading ? (
          <div
            className={cn(
              "border-t",
              wantsRow && "@lg:w-64 @lg:shrink-0 @lg:border-t-0 @lg:border-l"
            )}
          >
            <OddsSkeleton />
          </div>
        ) : null}
      </div>
    </div>
  )
}

export function MatchCard(props: MatchCardProps) {
  if (props.loading) {
    return (
      <MatchCardSkeleton
        className={props.className}
        oddsLoading={props.oddsLoading}
        oddsPosition={props.oddsPosition}
      />
    )
  }

  const {
    status,
    kickoff,
    elapsed,
    timeFormat = "24h",
    home,
    away,
    homeScore,
    awayScore,
    redCardPosition = "right",
    odds,
    oddsLoading,
    oddsPosition = "bottom",
    selectedOddsId,
    onSelectOdds,
    className,
  } = props

  const showScore = status !== "scheduled"
  const showRedCards = status !== "scheduled"
  const isFinished = status === "finished"
  const isLive = showScore && !isFinished
  const hasScores = homeScore != null && awayScore != null
  const homeLost = isFinished && hasScores && homeScore < awayScore
  const awayLost = isFinished && hasScores && awayScore < homeScore
  const hasOdds = Boolean(odds && odds.options.length > 0)
  const showOddsSlot = hasOdds || (oddsLoading && !odds)
  // @container below falls back to stacked under @lg regardless of oddsPosition.
  const wantsRow = showOddsSlot && oddsPosition === "right"

  const oddsCard = hasOdds ? (
    <OddsSelector
      variant="bare"
      options={odds!.options}
      selectedId={selectedOddsId}
      onSelect={onSelectOdds}
      className="w-full"
    />
  ) : showOddsSlot ? (
    <OddsSkeleton />
  ) : null

  return (
    <div
      className={cn(
        "@container w-full overflow-hidden rounded-xl border bg-card text-card-foreground",
        className
      )}
    >
      <div className={cn(wantsRow && "@lg:flex @lg:items-stretch")}>
        <div className={cn("flex flex-1 gap-3 px-3 py-3", wantsRow && "@lg:min-w-0")}>
          <div className="flex w-11 shrink-0 items-center justify-center border-r pr-3 text-center">
            <LiveIndicator
              variant="plain"
              status={status}
              kickoff={kickoff}
              elapsed={elapsed}
              timeFormat={timeFormat}
            />
          </div>
          <div className="flex min-w-0 flex-1 flex-col justify-center gap-2">
            <TeamRow
              team={home}
              score={homeScore}
              showScore={showScore}
              showRedCards={showRedCards}
              redCardPosition={redCardPosition}
              live={isLive}
              dimmed={homeLost}
            />
            <TeamRow
              team={away}
              score={awayScore}
              showScore={showScore}
              showRedCards={showRedCards}
              redCardPosition={redCardPosition}
              live={isLive}
              dimmed={awayLost}
            />
          </div>
        </div>
        {showOddsSlot ? (
          <div
            className={cn(
              "border-t",
              wantsRow && "@lg:w-64 @lg:shrink-0 @lg:border-t-0 @lg:border-l"
            )}
          >
            {oddsCard}
          </div>
        ) : null}
      </div>
    </div>
  )
}

import { Clock, Pause } from "lucide-react"

import { cn } from "@/lib/utils"
import { Badge } from "@/components/ui/badge"

export type LiveIndicatorStatus =
  | "scheduled"
  | "live"
  | "paused"
  | "intermission"
  | "interrupted"
  | "finished"

export interface LiveIndicatorProps {
  status: LiveIndicatorStatus
  /** Kickoff time, shown when status is "scheduled". */
  kickoff?: Date | string
  /**
   * Elapsed match clock, shown when status is "live", "paused",
   * "intermission", or "interrupted" (e.g. "67'", "HT").
   */
  elapsed?: string
  /**
   * "badge" (default) renders a filled pill, for standalone use. "plain"
   * renders just the colored label with no background, for dense layouts
   * like Match Card's status column.
   */
  variant?: "badge" | "plain"
  /**
   * Clock format for the kickoff time.
   *
   * @defaultValue "24h"
   */
  timeFormat?: "12h" | "24h"
  className?: string
}

function formatKickoff(kickoff: Date | string, timeFormat: "12h" | "24h" = "24h") {
  const date = typeof kickoff === "string" ? new Date(kickoff) : kickoff
  return date.toLocaleTimeString(undefined, {
    hour: "numeric",
    minute: "2-digit",
    hour12: timeFormat === "12h",
  })
}

function formatKickoffDate(kickoff: Date | string) {
  const date = typeof kickoff === "string" ? new Date(kickoff) : kickoff
  return date.toLocaleDateString(undefined, {
    day: "2-digit",
    month: "2-digit",
  })
}

const stoppedPlayLabel: Record<"paused" | "intermission" | "interrupted", string> = {
  paused: "Paused",
  intermission: "Intermission",
  interrupted: "Interrupted",
}

export function LiveIndicator({
  status,
  kickoff,
  elapsed,
  variant = "badge",
  timeFormat = "24h",
  className,
}: LiveIndicatorProps) {
  if (variant === "plain") {
    if (status === "live") {
      return (
        <span className={cn("text-xs font-bold leading-tight text-destructive tabular-nums", className)}>
          {elapsed ?? "LIVE"}
        </span>
      )
    }

    if (status === "paused" || status === "intermission" || status === "interrupted") {
      return (
        <span
          className={cn(
            "text-xs font-bold leading-tight text-amber-600 tabular-nums dark:text-amber-400",
            className
          )}
        >
          {elapsed ?? stoppedPlayLabel[status]}
        </span>
      )
    }

    if (status === "finished") {
      return (
        <div className={cn("flex flex-col items-center gap-1", className)}>
          <span className="text-xs font-bold leading-tight text-muted-foreground tabular-nums">
            {elapsed ?? "FT"}
          </span>
          {kickoff ? (
            <span className="text-xs leading-tight text-muted-foreground tabular-nums">
              {formatKickoffDate(kickoff)}
            </span>
          ) : null}
        </div>
      )
    }

    return (
      <span className={cn("text-xs font-medium leading-tight text-muted-foreground tabular-nums", className)}>
        {kickoff ? formatKickoff(kickoff, timeFormat) : "—"}
      </span>
    )
  }

  if (status === "live") {
    return (
      <Badge
        variant="destructive"
        className={cn("gap-1.5 border-transparent bg-destructive text-destructive-foreground", className)}
      >
        <span className="relative flex size-1.5">
          <span className="absolute inline-flex size-full animate-ping rounded-full bg-destructive-foreground/60" />
          <span className="relative inline-flex size-1.5 rounded-full bg-destructive-foreground" />
        </span>
        {elapsed ?? "LIVE"}
      </Badge>
    )
  }

  if (status === "paused" || status === "intermission" || status === "interrupted") {
    return (
      <Badge
        variant="outline"
        className={cn(
          "gap-1.5 border-transparent bg-amber-500/15 text-amber-600 dark:text-amber-400",
          className
        )}
      >
        <Pause className="size-3" />
        {elapsed ?? stoppedPlayLabel[status]}
      </Badge>
    )
  }

  if (status === "finished") {
    return (
      <Badge variant="secondary" className={className}>
        Finished
      </Badge>
    )
  }

  return (
    <Badge variant="outline" className={cn("gap-1", className)}>
      <Clock className="size-3" />
      {kickoff ? formatKickoff(kickoff, timeFormat) : "Scheduled"}
    </Badge>
  )
}

"use client"

import { useState } from "react"
import { ChevronDown, LayoutGrid, SlidersHorizontal } from "lucide-react"
import { cn } from "@/lib/utils"

export type OddsMovement = "up" | "down" | "flat"

export interface OddsOption {
  id: string
  /** Selection label, e.g. "1", "X", "2" or a team name / "Draw". */
  label: string
  /** Formatted price, e.g. "1.85". */
  price: string
  movement?: OddsMovement
  suspended?: boolean
}

/**
 * One market rendered as a two-column row, e.g. Over/Under at a single
 * goal threshold. Use `lines` (a market per row) instead of `options` (a
 * flat row of a single market) for bet types that post one market per
 * line — see the "Multiple Lines" example.
 */
export interface OddsLine {
  id: string
  /** Short label for the line itself, e.g. "2.5" — shown above the slider in slider view. Omit if there's no natural short label. */
  label?: string
  over: OddsOption
  under: OddsOption
}

export interface OddsSelectorProps {
  /** Market name shown as a header above the options, e.g. "Match Result". Omit to render just the options. */
  label?: string
  /** A single market's selections, laid out in one row. Ignored when `lines` is set. */
  options?: OddsOption[]
  /** Id of the currently selected option, for `options` mode. */
  selectedId?: string
  /** Called with the pressed option's id, or `undefined` when pressing the already-selected option deselects it. For `options` mode. */
  onSelect?: (id: string | undefined) => void
  /** Several markets, one per row — e.g. every Over/Under goal threshold stacked in one card. Takes over `options` when set. */
  lines?: OddsLine[]
  /** Ids of every currently selected option across `lines` — unlike `options`, more than one row can be selected at once. */
  selectedLineIds?: string[]
  /** Called with a pressed option's id and the resulting selected state (not a bare toggle), for `lines` mode. */
  onSelectLine?: (id: string, selected: boolean) => void
  /**
   * Ids that render as unavailable — e.g. because they're logically
   * incompatible with the current selection. Applies to both `options`
   * and `lines`. Computed externally (e.g. via a conflict adapter) and
   * passed in; OddsSelector never decides this itself. Unlike
   * `suspended`, a disabled option still shows its real price — it's
   * fully priced and available, just not currently combinable.
   */
  disabledIds?: string[]
  /** Adds a header toggle to browse `lines` one at a time via a slider instead of a stacked list. No effect with fewer than 2 lines. */
  enableSliderView?: boolean
  /** Adds a header toggle to collapse the selector down to just its header. Requires `label` (or `lines`/`enableSliderView`) to have a header to put it in. */
  collapsible?: boolean
  /**
   * "card" (default) renders its own border/background, for standalone
   * use. "bare" drops that chrome — for embedding inside another card
   * (e.g. Match Card's odds row) without a card-in-a-card look.
   */
  variant?: "card" | "bare"
  className?: string
}

// A price shortening (going down) means the market now thinks the outcome
// is more likely — the conventional "hot" direction in real odds boards,
// shown green. Drifting (going up) means the opposite, shown red. Same
// mechanical rule regardless of market type.
const movementColor: Record<OddsMovement, string> = {
  up: "text-destructive",
  down: "text-emerald-600 dark:text-emerald-500",
  flat: "",
}

function OddsOptionButton({
  option,
  selected,
  disabled,
  onClick,
  layout,
}: {
  option: OddsOption
  selected: boolean
  /** Conflict-disabled, distinct from `option.suspended` — still shows the real price. */
  disabled?: boolean
  onClick: () => void
  layout: "column" | "row"
}) {
  const inactive = option.suspended || disabled
  return (
    <button
      type="button"
      disabled={inactive}
      onClick={(e) => {
        e.stopPropagation()
        onClick()
      }}
      className={cn(
        "flex min-w-0 transition-colors",
        layout === "column"
          ? "flex-col items-center justify-center gap-0.5 px-2 py-2.5"
          : "items-center justify-between gap-2 px-3 py-2.5 text-left",
        selected ? "bg-primary text-primary-foreground" : "hover:bg-accent/50",
        inactive && "pointer-events-none opacity-50"
      )}
    >
      <span
        className={cn(
          "truncate text-xs",
          layout === "column" && "max-w-full",
          selected ? "text-primary-foreground/70" : "text-muted-foreground"
        )}
      >
        {option.label}
      </span>
      <span
        className={cn(
          "text-sm font-semibold",
          !selected && !option.suspended && option.movement && movementColor[option.movement]
        )}
      >
        {option.suspended ? "—" : option.price}
      </span>
    </button>
  )
}

function OddsLineRow({
  line,
  selectedIds,
  disabledIds,
  onToggle,
}: {
  line: OddsLine
  selectedIds: string[]
  disabledIds?: string[]
  onToggle: (id: string, selected: boolean) => void
}) {
  return (
    <div className="grid grid-cols-2 divide-x">
      {[line.over, line.under].map((option) => {
        const selected = selectedIds.includes(option.id)
        return (
          <OddsOptionButton
            key={option.id}
            option={option}
            layout="row"
            selected={selected}
            disabled={disabledIds?.includes(option.id)}
            onClick={() => onToggle(option.id, !selected)}
          />
        )
      })}
    </div>
  )
}

// Starts the slider on the line closest to an even split (e.g. 1.90/2.00)
// rather than always the first/lowest threshold, which is often the most
// lopsided line (e.g. 1.17/4.45).
function mostBalancedIndex(lines: OddsLine[]): number {
  let bestIndex = 0
  let bestSpread = Infinity
  lines.forEach((line, i) => {
    const spread = Math.abs(parseFloat(line.over.price) - parseFloat(line.under.price))
    if (spread < bestSpread) {
      bestIndex = i
      bestSpread = spread
    }
  })
  return bestIndex
}

function OddsLinesSlider({
  lines,
  selectedIds,
  disabledIds,
  onSelectLine,
}: {
  lines: OddsLine[]
  selectedIds: string[]
  disabledIds?: string[]
  onSelectLine?: (id: string, selected: boolean) => void
}) {
  const [index, setIndex] = useState(() => mostBalancedIndex(lines))
  // Lines can arrive/change size as live data updates — clamp rather than
  // point past the end.
  const currentIndex = Math.min(index, lines.length - 1)
  const line = lines[currentIndex]

  return (
    <div className="flex flex-col">
      <OddsLineRow
        line={line}
        selectedIds={selectedIds}
        disabledIds={disabledIds}
        onToggle={(id, selected) => onSelectLine?.(id, selected)}
      />
      <div className="flex flex-col items-center gap-1 border-t px-3 py-3">
        {line.label ? (
          <span className="text-sm font-semibold text-card-foreground">{line.label}</span>
        ) : null}
        <input
          type="range"
          min={0}
          max={lines.length - 1}
          step={1}
          value={currentIndex}
          onChange={(e) => setIndex(Number(e.target.value))}
          className="w-full cursor-pointer accent-primary"
          aria-label="Select line"
        />
      </div>
    </div>
  )
}

export function OddsSelector({
  label,
  options = [],
  selectedId,
  onSelect,
  lines,
  selectedLineIds = [],
  onSelectLine,
  disabledIds,
  enableSliderView = false,
  collapsible = false,
  variant = "card",
  className,
}: OddsSelectorProps) {
  const [collapsed, setCollapsed] = useState(false)
  const [linesView, setLinesView] = useState<"list" | "slider">("list")
  const showLinesToggle = Boolean(lines && lines.length > 1 && enableSliderView)
  const showHeader = Boolean(label) || showLinesToggle || collapsible

  return (
    <div
      className={cn(
        "flex h-full flex-col overflow-hidden",
        variant === "card" && "rounded-xl border bg-card",
        className
      )}
    >
      {showHeader ? (
        <div
          className={cn(
            "flex h-10 items-center justify-between gap-2 py-2 pl-3 pr-2 border-b",
            collapsed && "border-b-transparent"
          )}
        >
          <span className="truncate text-sm font-medium text-card-foreground">{label}</span>
          <div className="flex items-center gap-1">
            {showLinesToggle ? (
              <div className="flex items-center gap-1 rounded-md border p-0.5">
                <button
                  type="button"
                  aria-label="List view"
                  aria-pressed={linesView === "list"}
                  onClick={() => setLinesView("list")}
                  className={cn(
                    "rounded p-1 transition-colors",
                    linesView === "list"
                      ? "bg-accent text-accent-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <LayoutGrid className="size-3.5" />
                </button>
                <button
                  type="button"
                  aria-label="Slider view"
                  aria-pressed={linesView === "slider"}
                  onClick={() => setLinesView("slider")}
                  className={cn(
                    "rounded p-1 transition-colors",
                    linesView === "slider"
                      ? "bg-accent text-accent-foreground"
                      : "text-muted-foreground hover:text-foreground"
                  )}
                >
                  <SlidersHorizontal className="size-3.5" />
                </button>
              </div>
            ) : null}
            {collapsible ? (
              <button
                type="button"
                aria-label={collapsed ? "Expand" : "Collapse"}
                aria-expanded={!collapsed}
                onClick={() => setCollapsed((c) => !c)}
                className="rounded p-1 text-muted-foreground transition-colors hover:text-foreground"
              >
                <ChevronDown className={cn("size-3.5 transition-transform", collapsed && "-rotate-90")} />
              </button>
            ) : null}
          </div>
        </div>
      ) : null}
      {!collapsed &&
        (lines ? (
          showLinesToggle && linesView === "slider" ? (
            <OddsLinesSlider
              lines={lines}
              selectedIds={selectedLineIds}
              disabledIds={disabledIds}
              onSelectLine={onSelectLine}
            />
          ) : (
            <div className="divide-y">
              {lines.map((line) => (
                <OddsLineRow
                  key={line.id}
                  line={line}
                  selectedIds={selectedLineIds}
                  disabledIds={disabledIds}
                  onToggle={(id, selected) => onSelectLine?.(id, selected)}
                />
              ))}
            </div>
          )
        ) : (
          <div className="grid flex-1 auto-cols-fr grid-flow-col divide-x">
            {options.map((option) => {
              const selected = option.id === selectedId
              return (
                <OddsOptionButton
                  key={option.id}
                  option={option}
                  layout="column"
                  selected={selected}
                  disabled={disabledIds?.includes(option.id)}
                  onClick={() => onSelect?.(selected ? undefined : option.id)}
                />
              )
            })}
          </div>
        ))}
    </div>
  )
}

"use client"

import { useState } from "react"
import { cn } from "@/lib/utils"

export interface EntityImageProps {
  src?: string | null
  /** Used for the alt text and the initials fallback. */
  name: string
  size?: "sm" | "default" | "lg"
  className?: string
}

const sizeClass: Record<NonNullable<EntityImageProps["size"]>, string> = {
  sm: "size-5",
  default: "size-8",
  lg: "size-10",
}

/**
 * Just the image — no background, border, or corner radius, so team crests
 * and region flags render at their native shape. Pass a `className` (e.g.
 * `size-6`) to override the size; it takes precedence over `size`.
 */
export function EntityImage({ src, name, size = "default", className }: EntityImageProps) {
  const [errored, setErrored] = useState(false)

  if (!src || errored) {
    return (
      <span
        className={cn(
          "flex shrink-0 items-center justify-center rounded-full bg-muted text-[0.6rem] font-medium text-muted-foreground",
          sizeClass[size],
          className
        )}
      >
        {name.slice(0, 2).toUpperCase()}
      </span>
    )
  }

  return (
    // eslint-disable-next-line @next/next/no-img-element -- framework-agnostic registry component, no next/image dependency
    <img
      src={src}
      alt={name}
      className={cn("shrink-0 object-contain", sizeClass[size], className)}
      onError={() => setErrored(true)}
    />
  )
}
